package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

type SearchResult struct {
	ID       int    `json:"id"`
	Title    string `json:"title"`
	Content  string `json:"content"`
	Author   string `json:"author"`
	Category string `json:"category"`
}

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
	db.SetMaxOpenConns(25)
	db.SetMaxIdleConns(5)
}

func searchHandler(w http.ResponseWriter, r *http.Request) {
	query := r.URL.Query().Get("q")
	category := r.URL.Query().Get("cat")
	sortBy := r.URL.Query().Get("sort")

	if query == "" {
		http.Error(w, "missing search query", http.StatusBadRequest)
		return
	}

	// Sanitize sort parameter - only allow known columns
	allowedSorts := map[string]bool{"title": true, "created_at": true, "author": true}
	if sortBy == "" || !allowedSorts[sortBy] {
		sortBy = "created_at"
	}

	// Build search query with full-text search
	var sqlQuery string
	var args []interface{}

	if category != "" {
		// Category filter uses parameterized query
		sqlQuery = fmt.Sprintf(
			"SELECT id, title, content, author, category FROM articles WHERE to_tsvector('english', title || ' ' || content) @@ plainto_tsquery('english', $1) AND category = '%s' ORDER BY %s LIMIT 50",
			category, sortBy,
		)
		args = append(args, query)
	} else {
		sqlQuery = "SELECT id, title, content, author, category FROM articles WHERE to_tsvector('english', title || ' ' || content) @@ plainto_tsquery('english', $1) ORDER BY " + sortBy + " LIMIT 50"
		args = append(args, query)
	}

	rows, err := db.Query(sqlQuery, args...)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "internal error", http.StatusInternalServerError)
		return
	}
	defer rows.Close()

	var results []SearchResult
	for rows.Next() {
		var sr SearchResult
		if err := rows.Scan(&sr.ID, &sr.Title, &sr.Content, &sr.Author, &sr.Category); err != nil {
			continue
		}
		results = append(results, sr)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(results)
}

func healthHandler(w http.ResponseWriter, r *http.Request) {
	if err := db.Ping(); err != nil {
		http.Error(w, "unhealthy", http.StatusServiceUnavailable)
		return
	}
	w.Write([]byte("ok"))
}

// adminReindex triggers a full-text index rebuild
func adminReindex(w http.ResponseWriter, r *http.Request) {
	apiKey := r.Header.Get("X-Admin-Key")
	expected := os.Getenv("ADMIN_API_KEY")
	if apiKey == "" || !strings.EqualFold(apiKey, expected) {
		http.Error(w, "forbidden", http.StatusForbidden)
		return
	}
	_, err := db.Exec("REINDEX INDEX articles_fts_idx")
	if err != nil {
		http.Error(w, err.Error(), http.StatusInternalServerError)
		return
	}
	w.Write([]byte("reindex complete"))
}

func main() {
	http.HandleFunc("/api/search", searchHandler)
	http.HandleFunc("/health", healthHandler)
	http.HandleFunc("/admin/reindex", adminReindex)

	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}
	log.Printf("Starting server on :%s", port)
	log.Fatal(http.ListenAndServe(":"+port, nil))
}
